<?php
declare(strict_types=1);
if (!defined('CWP_BOOT')) { http_response_code(404); exit; }

 $status=is_string($_GET['status']??null)?$_GET['status']:'';$search=is_string($_GET['q']??null)?substr($_GET['q'],0,100):'';$pg=max(1,(int)($_GET['p']??1));$where='1=1';$params=[];
 if(in_array($status,['new','contacted','qualified','proposal','won','closed','spam'],true)){$where.=' AND status=?';$params[]=$status;}
 if($search!==''){$where.=' AND (name LIKE ? OR email LIKE ? OR company LIKE ? OR reference LIKE ?)';for($i=0;$i<4;$i++)$params[]='%'.$search.'%';}
 $count=(int)one('SELECT COUNT(*) AS n FROM '.table('leads').' WHERE '.$where,$params)['n'];$pages=max(1,(int)ceil($count/30));$pg=min($pg,$pages);$rows=all('SELECT * FROM '.table('leads').' WHERE '.$where.' ORDER BY id DESC LIMIT 30 OFFSET '.(($pg-1)*30),$params);
 ?><div class="admin-toolbar"><p>Every accepted inquiry is stored here before email notification is attempted.</p><form method="post" action="<?=esc(admin_url('leads'))?>"><?php admin_action('leads_export');?><button class="btn outline small">Export All Inquiries ↓</button></form></div><form class="filter-form admin-card" method="get" action="<?=esc(site_url('admin/index.php'))?>"><input type="hidden" name="view" value="leads"><label>Find an inquiry<input name="q" value="<?=esc($search)?>" placeholder="Name, company, email or reference" maxlength="100"></label><?php admin_select('status','Status',[''=>'All statuses','new'=>'New','contacted'=>'Contacted','qualified'=>'Qualified','proposal'=>'Proposal sent','won'=>'Won','closed'=>'Closed','spam'=>'Spam'],$status);?><button class="btn outline small">Filter →</button></form><?php if(!$rows):empty_admin('No inquiries in this view.','New conversations from your website will appear here.');else:?><div class="admin-card table-wrap"><table><thead><tr><th>Name / Business</th><th>Project</th><th>Status</th><th>Notification</th><th>Received</th><th></th></tr></thead><tbody><?php foreach($rows as $l):?><tr><td><strong><?=esc($l['name'])?></strong><small><?=esc($l['company']?:$l['email'])?></small></td><td><?=esc($l['service'])?><small><?=esc($l['budget'])?></small></td><td><?=badge($l['status'])?></td><td><?=badge($l['notification_status'])?></td><td><?=format_date($l['created_at'])?></td><td><a class="row-link" href="<?=esc(admin_url('lead',['id'=>$l['id']]))?>">Open ↗</a></td></tr><?php endforeach;?></tbody></table></div><div class="pagination"><span><?=$count?> inquiries · Page <?=$pg?> of <?=$pages?></span><?php if($pg>1):?><a href="<?=esc(admin_url('leads',['status'=>$status,'q'=>$search,'p'=>$pg-1]))?>">← Previous</a><?php endif;if($pg<$pages):?><a href="<?=esc(admin_url('leads',['status'=>$status,'q'=>$search,'p'=>$pg+1]))?>">Next →</a><?php endif;?></div><?php endif;
